-- ===========================================================================
-- DWH E-commerce Marketplace (v2) · schema royal_canin · PostgreSQL
-- generated by erd/build_ddl.py from build_erd.py + staging_columns.json
-- layer: STG_ (as-is) -> M_ (master) -> T_ (transaksi) -> DM_ (datamart) + LOG_
-- ===========================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS royal_canin;

-- Zona waktu: session script ini + default database (permanen untuk koneksi baru).
SET TIME ZONE 'Asia/Jakarta';
DO $do$
BEGIN
    EXECUTE format('ALTER DATABASE %I SET timezone = %L', current_database(), 'Asia/Jakarta');
EXCEPTION WHEN insufficient_privilege THEN
    RAISE NOTICE 'Tidak punya hak ALTER DATABASE %: minta DBA set timezone = Asia/Jakarta', current_database();
END
$do$;

-- Jam di file marketplace = jam dinding WIB tanpa offset. Fungsi ini membacanya sebagai
-- Asia/Jakarta apa pun TimeZone session-nya. Nilai kosong / '-' -> NULL.
CREATE OR REPLACE FUNCTION royal_canin.to_jakarta_ts(p_value text, p_format text)
RETURNS timestamp with time zone
LANGUAGE sql STABLE AS $function$
    SELECT CASE WHEN p_value IS NULL OR btrim(p_value) IN ('', '-') THEN NULL
                ELSE to_timestamp(btrim(p_value), p_format)::timestamp AT TIME ZONE 'Asia/Jakarta' END
$function$;
COMMENT ON FUNCTION royal_canin.to_jakarta_ts(text, text) IS 'parse jam dinding WIB dari file mentah -> timestamptz; format: m_channel.order_ts_format';

-- Tanggal kalender WIB dari timestamptz (dipakai agregasi harian / datamart).
CREATE OR REPLACE FUNCTION royal_canin.jakarta_date(p_ts timestamp with time zone)
RETURNS date
LANGUAGE sql IMMUTABLE AS $function$
    SELECT (p_ts AT TIME ZONE 'Asia/Jakarta')::date
$function$;

CREATE OR REPLACE FUNCTION royal_canin.set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $function$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$function$;


-- ---------------------------------------------------------------------------
-- LOG ETL
-- ---------------------------------------------------------------------------

CREATE TABLE royal_canin.log_etl_run (
    run_id                       bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    started_at                   timestamp with time zone NOT NULL DEFAULT now(),
    finished_at                  timestamp with time zone,
    status                       text NOT NULL DEFAULT 'RUNNING',
    channels                     text,
    source_files                 text,
    triggered_by                 text,
    error_message                text,
    CONSTRAINT pk_log_etl_run PRIMARY KEY (run_id),
    CONSTRAINT ck_log_etl_run_1 CHECK (status IN ('RUNNING','SUCCESS','FAILED'))
);
COMMENT ON TABLE royal_canin.log_etl_run IS '1 baris per eksekusi ETL';
COMMENT ON COLUMN royal_canin.log_etl_run.started_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.log_etl_run.finished_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.log_etl_step (
    step_id                      bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    run_id                       bigint NOT NULL,
    step_seq                     integer NOT NULL,
    step_name                    text NOT NULL,
    channel_code                 text,
    target_table                 text,
    status                       text NOT NULL,
    rows_read                    integer,
    rows_inserted                integer,
    rows_updated                 integer,
    rows_rejected                integer,
    message                      text,
    logged_at                    timestamp with time zone DEFAULT now(),
    CONSTRAINT pk_log_etl_step PRIMARY KEY (step_id),
    CONSTRAINT uq_log_etl_step_run_id_step_seq UNIQUE (run_id, step_seq),
    CONSTRAINT ck_log_etl_step_1 CHECK (status IN ('RUNNING','SUCCESS','FAILED','SKIPPED')),
    CONSTRAINT fk_log_etl_step_run_id FOREIGN KEY (run_id) REFERENCES royal_canin.log_etl_run (run_id)
);
COMMENT ON TABLE royal_canin.log_etl_step IS '1 baris per langkah / tabel';
COMMENT ON COLUMN royal_canin.log_etl_step.logged_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';


