COMMENT ON COLUMN royal_canin.stg_unique_sku.dq_note IS 'daftar dipisah koma: missing_seller_sku, missing_marketplace_sku, seller_sku_changed, shared_seller_sku';

-- ---------------------------------------------------------------------------
-- MASTER DATA
-- ---------------------------------------------------------------------------

CREATE TABLE royal_canin.m_channel (
    channel_id                   integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    channel_code                 text NOT NULL,
    channel_name                 text NOT NULL,
    sku_source_column            text,
    order_ts_format              text NOT NULL,
    gmv2_dedup_by_order          boolean NOT NULL DEFAULT false,
    is_active                    boolean NOT NULL DEFAULT true,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_m_channel PRIMARY KEY (channel_id),
    CONSTRAINT uq_m_channel_channel_code UNIQUE (channel_code)
);
COMMENT ON TABLE royal_canin.m_channel IS '5 channel · atribut aturan GMV 2';
COMMENT ON COLUMN royal_canin.m_channel.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.m_city (
    city_id                      integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    city_name                    text NOT NULL,
    province_name                text NOT NULL,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_m_city PRIMARY KEY (city_id),
    CONSTRAINT uq_m_city_city_name_province_name UNIQUE (city_name, province_name)
);
COMMENT ON TABLE royal_canin.m_city IS 'kota + provinsi sesuai penulisan marketplace (tanpa normalisasi)';
COMMENT ON COLUMN royal_canin.m_city.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.m_sku (
    sku_id                       integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    sku_master_code              text NOT NULL,
    master_sku                   text,
    product_name                 text NOT NULL,
    sku_type                     text NOT NULL DEFAULT 'unknown',
    bundle_flag                  boolean NOT NULL DEFAULT false,
    first_order_at               timestamp with time zone,
    dq_flag                      text,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    updated_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_m_sku PRIMARY KEY (sku_id),
    CONSTRAINT uq_m_sku_sku_master_code UNIQUE (sku_master_code),
    CONSTRAINT uq_m_sku_master_sku UNIQUE (master_sku),
    CONSTRAINT ck_m_sku_1 CHECK (sku_type IN ('single','multipack','bundle','free_gift','near_expired','unknown'))
);
CREATE TRIGGER trg_m_sku_updated_at BEFORE UPDATE ON royal_canin.m_sku
    FOR EACH ROW EXECUTE FUNCTION royal_canin.set_updated_at();
COMMENT ON TABLE royal_canin.m_sku IS 'golden record lintas channel · 1 baris per produk fisik';
COMMENT ON COLUMN royal_canin.m_sku.first_order_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.m_sku.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.m_sku.updated_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.m_sku_alias (
    sku_code                     text NOT NULL,
    sku_id                       integer NOT NULL,
    is_master_code               boolean NOT NULL DEFAULT false,
    first_seen_at                timestamp with time zone,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_m_sku_alias PRIMARY KEY (sku_code),
    CONSTRAINT fk_m_sku_alias_sku_id FOREIGN KEY (sku_id) REFERENCES royal_canin.m_sku (sku_id)
);
CREATE INDEX ix_m_sku_alias_sku_id ON royal_canin.m_sku_alias (sku_id);
COMMENT ON TABLE royal_canin.m_sku_alias IS 'semua kode seller SKU (bersih) → master · lookup ETL';
COMMENT ON COLUMN royal_canin.m_sku_alias.first_seen_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.m_sku_alias.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.m_platform_sku (
    platform_sku_id              integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    channel_id                   integer NOT NULL,
    merchant_sku                 text NOT NULL,
    sku_id                       integer NOT NULL,
    current_seller_sku           text,
    product_name                 text,
    is_on_master_sku             boolean NOT NULL DEFAULT false,
    first_order_at               timestamp with time zone,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    updated_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_m_platform_sku PRIMARY KEY (platform_sku_id),
    CONSTRAINT uq_m_platform_sku_channel_id_merchant_sku UNIQUE (channel_id, merchant_sku),
    CONSTRAINT fk_m_platform_sku_sku_id FOREIGN KEY (sku_id) REFERENCES royal_canin.m_sku (sku_id),
    CONSTRAINT fk_m_platform_sku_channel_id FOREIGN KEY (channel_id) REFERENCES royal_canin.m_channel (channel_id)
);
CREATE INDEX ix_m_platform_sku_sku_id ON royal_canin.m_platform_sku (sku_id);
CREATE TRIGGER trg_m_platform_sku_updated_at BEFORE UPDATE ON royal_canin.m_platform_sku
    FOR EACH ROW EXECUTE FUNCTION royal_canin.set_updated_at();
COMMENT ON TABLE royal_canin.m_platform_sku IS '1 baris per listing marketplace (channel × merchant SKU)';
COMMENT ON COLUMN royal_canin.m_platform_sku.first_order_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.m_platform_sku.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.m_platform_sku.updated_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.m_sku_history (
    history_id                   bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    platform_sku_id              integer NOT NULL,
    sku_id                       integer NOT NULL,
    version                      integer NOT NULL,
    old_seller_sku               text,
    new_seller_sku               text NOT NULL,
    valid_from                   timestamp with time zone,
    changed_at                   timestamp with time zone NOT NULL,
    dq_flag                      text,
    CONSTRAINT pk_m_sku_history PRIMARY KEY (history_id),
    CONSTRAINT uq_m_sku_history_platform_sku_id_version UNIQUE (platform_sku_id, version),
    CONSTRAINT ck_m_sku_history_1 CHECK (version >= 2),
    CONSTRAINT ck_m_sku_history_2 CHECK (changed_at >= valid_from),
    CONSTRAINT fk_m_sku_history_platform_sku_id FOREIGN KEY (platform_sku_id) REFERENCES royal_canin.m_platform_sku (platform_sku_id),
    CONSTRAINT fk_m_sku_history_sku_id FOREIGN KEY (sku_id) REFERENCES royal_canin.m_sku (sku_id)
);
CREATE INDEX ix_m_sku_history_sku_id ON royal_canin.m_sku_history (sku_id);
COMMENT ON TABLE royal_canin.m_sku_history IS 'perubahan seller SKU pada listing yang sama (SCD 2)';
COMMENT ON COLUMN royal_canin.m_sku_history.valid_from IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.m_sku_history.changed_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.m_sku_bundle (
    bundle_sku_id                integer NOT NULL,
    component_seq                integer NOT NULL,
    component_sku_id             integer,
    component_sku_code           text NOT NULL,
    qty                          integer NOT NULL,
    component_price              numeric(18,2),
    price_ratio                  numeric(9,8),
    dq_flag                      text,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_m_sku_bundle PRIMARY KEY (bundle_sku_id, component_seq),
    CONSTRAINT ck_m_sku_bundle_1 CHECK (qty > 0),
    CONSTRAINT ck_m_sku_bundle_2 CHECK (component_seq > 0),
    CONSTRAINT ck_m_sku_bundle_3 CHECK (component_price >= 0),
    CONSTRAINT ck_m_sku_bundle_4 CHECK (price_ratio BETWEEN 0 AND 1),
    CONSTRAINT fk_m_sku_bundle_bundle_sku_id FOREIGN KEY (bundle_sku_id) REFERENCES royal_canin.m_sku (sku_id) ON DELETE CASCADE,
    CONSTRAINT fk_m_sku_bundle_component_sku_id FOREIGN KEY (component_sku_id) REFERENCES royal_canin.m_sku (sku_id)
);
CREATE INDEX ix_m_sku_bundle_component_sku_id ON royal_canin.m_sku_bundle (component_sku_id);
COMMENT ON TABLE royal_canin.m_sku_bundle IS 'bill of materials dari file bundle · komponen sudah diratakan (bundle dalam bundle diuraikan sampai komponen akhir)';
COMMENT ON COLUMN royal_canin.m_sku_bundle.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';


-- ---------------------------------------------------------------------------
-- TRANSAKSI
-- ---------------------------------------------------------------------------

CREATE TABLE royal_canin.t_order (
    order_id                     bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    channel_id                   integer NOT NULL,
    order_no                     text NOT NULL,
    city_id                      integer,
    order_status                 text,
    order_created_at             timestamp with time zone NOT NULL,
    order_paid_at                timestamp with time zone,
    order_shipped_at             timestamp with time zone,
    order_completed_at           timestamp with time zone,
    order_date                   date GENERATED ALWAYS AS ((order_created_at AT TIME ZONE 'Asia/Jakarta')::date) STORED NOT NULL,
    buyer_username               text,
    warehouse_name               text,
    delivery_option              text,
    payment_method               text,
    item_line_count              integer,
    total_quantity               integer,
    shipping_fee                 numeric(18,2),
    gmv_2                        numeric(18,2),
    etl_run_id                   bigint,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    updated_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_t_order PRIMARY KEY (order_id),
    CONSTRAINT uq_t_order_channel_id_order_no UNIQUE (channel_id, order_no),
    CONSTRAINT ck_t_order_1 CHECK (item_line_count >= 0),
    CONSTRAINT ck_t_order_2 CHECK (total_quantity >= 0),
    CONSTRAINT fk_t_order_channel_id FOREIGN KEY (channel_id) REFERENCES royal_canin.m_channel (channel_id),
    CONSTRAINT fk_t_order_city_id FOREIGN KEY (city_id) REFERENCES royal_canin.m_city (city_id),
    CONSTRAINT fk_t_order_etl_run_id FOREIGN KEY (etl_run_id) REFERENCES royal_canin.log_etl_run (run_id)
);
CREATE INDEX ix_t_order_city_id ON royal_canin.t_order (city_id);
CREATE INDEX ix_t_order_etl_run_id ON royal_canin.t_order (etl_run_id);
CREATE TRIGGER trg_t_order_updated_at BEFORE UPDATE ON royal_canin.t_order
    FOR EACH ROW EXECUTE FUNCTION royal_canin.set_updated_at();
COMMENT ON TABLE royal_canin.t_order IS 'grain: 1 baris per order (header)';
COMMENT ON COLUMN royal_canin.t_order.order_created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_order.order_paid_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_order.order_shipped_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_order.order_completed_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_order.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_order.updated_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.t_order_detail (
    order_detail_id              bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    order_id                     bigint NOT NULL,
    line_key                     text NOT NULL,
    platform_sku_id              integer,
    sku_id                       integer,
    seller_sku                   text,
    product_name                 text,
    item_status                  text,
    quantity                     integer NOT NULL,
    return_quantity              integer DEFAULT 0,
    unit_price                   numeric(18,2),
    seller_discount              numeric(18,2),
    platform_discount            numeric(18,2),
    gmv_1                        numeric(18,2),
    unit_sold                    integer,
    is_bundle                    boolean NOT NULL DEFAULT false,
    etl_run_id                   bigint,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    updated_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_t_order_detail PRIMARY KEY (order_detail_id),
    CONSTRAINT uq_t_order_detail_order_id_line_key UNIQUE (order_id, line_key),
    CONSTRAINT ck_t_order_detail_1 CHECK (quantity >= 0),
    CONSTRAINT ck_t_order_detail_2 CHECK (return_quantity >= 0),
    CONSTRAINT ck_t_order_detail_3 CHECK (unit_sold >= 0),
    CONSTRAINT fk_t_order_detail_order_id FOREIGN KEY (order_id) REFERENCES royal_canin.t_order (order_id) ON DELETE CASCADE,
    CONSTRAINT fk_t_order_detail_platform_sku_id FOREIGN KEY (platform_sku_id) REFERENCES royal_canin.m_platform_sku (platform_sku_id),
    CONSTRAINT fk_t_order_detail_sku_id FOREIGN KEY (sku_id) REFERENCES royal_canin.m_sku (sku_id),
    CONSTRAINT fk_t_order_detail_etl_run_id FOREIGN KEY (etl_run_id) REFERENCES royal_canin.log_etl_run (run_id)
);
CREATE INDEX ix_t_order_detail_platform_sku_id ON royal_canin.t_order_detail (platform_sku_id);
CREATE INDEX ix_t_order_detail_sku_id ON royal_canin.t_order_detail (sku_id);
CREATE INDEX ix_t_order_detail_etl_run_id ON royal_canin.t_order_detail (etl_run_id);
CREATE TRIGGER trg_t_order_detail_updated_at BEFORE UPDATE ON royal_canin.t_order_detail
    FOR EACH ROW EXECUTE FUNCTION royal_canin.set_updated_at();
COMMENT ON TABLE royal_canin.t_order_detail IS 'grain: 1 baris per item / SKU dalam order';
COMMENT ON COLUMN royal_canin.t_order_detail.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_order_detail.updated_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.t_order_detail_dq (
    order_detail_id              bigint NOT NULL,
    dq_flag                      text NOT NULL,
    CONSTRAINT pk_t_order_detail_dq PRIMARY KEY (order_detail_id),
    CONSTRAINT fk_t_order_detail_dq_order_detail_id FOREIGN KEY (order_detail_id) REFERENCES royal_canin.t_order_detail (order_detail_id) ON DELETE CASCADE
);
COMMENT ON TABLE royal_canin.t_order_detail_dq IS 'baris item dengan catatan kualitas data; equal_split = bundle tanpa harga komponen (semua 0 / kosong), nilai dibagi menurut qty';

CREATE TABLE royal_canin.t_traffic (
    traffic_id                   bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    channel_id                   integer NOT NULL,
    period_start                 date NOT NULL,
    period_end                   date NOT NULL,
    visitor                      integer NOT NULL,
    etl_run_id                   bigint,
    created_at                   timestamp with time zone NOT NULL DEFAULT now(),
    updated_at                   timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pk_t_traffic PRIMARY KEY (traffic_id),
    CONSTRAINT uq_t_traffic_channel_id_period_start_period_end UNIQUE (channel_id, period_start, period_end),
    CONSTRAINT ck_t_traffic_1 CHECK (period_end >= period_start),
    CONSTRAINT ck_t_traffic_2 CHECK (visitor >= 0),
    CONSTRAINT fk_t_traffic_channel_id FOREIGN KEY (channel_id) REFERENCES royal_canin.m_channel (channel_id),
    CONSTRAINT fk_t_traffic_etl_run_id FOREIGN KEY (etl_run_id) REFERENCES royal_canin.log_etl_run (run_id)
);
CREATE INDEX ix_t_traffic_etl_run_id ON royal_canin.t_traffic (etl_run_id);
CREATE TRIGGER trg_t_traffic_updated_at BEFORE UPDATE ON royal_canin.t_traffic
    FOR EACH ROW EXECUTE FUNCTION royal_canin.set_updated_at();
COMMENT ON TABLE royal_canin.t_traffic IS 'periode · channel · visitor';
COMMENT ON COLUMN royal_canin.t_traffic.period_start IS 'tanggal kalender WIB (Asia/Jakarta)';
COMMENT ON COLUMN royal_canin.t_traffic.period_end IS 'tanggal kalender WIB (Asia/Jakarta)';
COMMENT ON COLUMN royal_canin.t_traffic.created_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';
COMMENT ON COLUMN royal_canin.t_traffic.updated_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';


-- ---------------------------------------------------------------------------
-- DATAMART
-- ---------------------------------------------------------------------------

CREATE TABLE royal_canin.dm_sales_daily (
    sales_date                   date NOT NULL,
    channel_id                   integer NOT NULL,
    city_id                      integer NOT NULL,
    warehouse_name               text NOT NULL,
    delivery_option              text NOT NULL,
    payment_method               text NOT NULL,
    gmv_1                        numeric(18,2),
    gmv_2                        numeric(18,2),
    order_count                  integer,
    buyer_count                  integer,
    unit_sold                    integer,
    aov                          numeric(18,2),
    aipo                         numeric(10,2),
    refreshed_at                 timestamp with time zone DEFAULT now(),
    CONSTRAINT pk_dm_sales_daily PRIMARY KEY (sales_date, channel_id, city_id, warehouse_name, delivery_option, payment_method),
    CONSTRAINT fk_dm_sales_daily_channel_id FOREIGN KEY (channel_id) REFERENCES royal_canin.m_channel (channel_id),
    CONSTRAINT fk_dm_sales_daily_city_id FOREIGN KEY (city_id) REFERENCES royal_canin.m_city (city_id)
);
CREATE INDEX ix_dm_sales_daily_channel_id ON royal_canin.dm_sales_daily (channel_id);
CREATE INDEX ix_dm_sales_daily_city_id ON royal_canin.dm_sales_daily (city_id);
COMMENT ON TABLE royal_canin.dm_sales_daily IS 'GMV1/2 · order · buyer · unit · AOV · AIPO';
COMMENT ON COLUMN royal_canin.dm_sales_daily.sales_date IS 'tanggal kalender WIB (Asia/Jakarta)';
COMMENT ON COLUMN royal_canin.dm_sales_daily.refreshed_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

CREATE TABLE royal_canin.dm_sales_sku_daily (
    sales_date                   date NOT NULL,
    channel_id                   integer NOT NULL,
    sku_id                       integer NOT NULL,
    order_count                  integer,
    quantity                     integer,
    unit_sold_component          integer,
    gmv_1                        numeric(18,2),
    refreshed_at                 timestamp with time zone DEFAULT now(),
    CONSTRAINT pk_dm_sales_sku_daily PRIMARY KEY (sales_date, channel_id, sku_id),
    CONSTRAINT fk_dm_sales_sku_daily_channel_id FOREIGN KEY (channel_id) REFERENCES royal_canin.m_channel (channel_id),
    CONSTRAINT fk_dm_sales_sku_daily_sku_id FOREIGN KEY (sku_id) REFERENCES royal_canin.m_sku (sku_id)
);
CREATE INDEX ix_dm_sales_sku_daily_channel_id ON royal_canin.dm_sales_sku_daily (channel_id);
CREATE INDEX ix_dm_sales_sku_daily_sku_id ON royal_canin.dm_sales_sku_daily (sku_id);
COMMENT ON TABLE royal_canin.dm_sales_sku_daily IS 'penjualan per SKU master lintas channel';
COMMENT ON COLUMN royal_canin.dm_sales_sku_daily.sales_date IS 'tanggal kalender WIB (Asia/Jakarta)';
COMMENT ON COLUMN royal_canin.dm_sales_sku_daily.refreshed_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';


-- ---------------------------------------------------------------------------
-- LOG ETL
-- ---------------------------------------------------------------------------

CREATE TABLE royal_canin.log_dq_issue (
    issue_id                     bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    run_id                       bigint,
    source_table                 text NOT NULL,
    dq_flag                      text NOT NULL,
    record_key                   text,
    sku_id                       integer,
    detail                       text,
    status                       text NOT NULL DEFAULT 'OPEN',
    logged_at                    timestamp with time zone DEFAULT now(),
    CONSTRAINT pk_log_dq_issue PRIMARY KEY (issue_id),
    CONSTRAINT ck_log_dq_issue_1 CHECK (status IN ('OPEN','CONFIRMED','FIXED','IGNORED')),
    CONSTRAINT fk_log_dq_issue_run_id FOREIGN KEY (run_id) REFERENCES royal_canin.log_etl_run (run_id),
    CONSTRAINT fk_log_dq_issue_sku_id FOREIGN KEY (sku_id) REFERENCES royal_canin.m_sku (sku_id)
);
CREATE INDEX ix_log_dq_issue_run_id ON royal_canin.log_dq_issue (run_id);
CREATE INDEX ix_log_dq_issue_sku_id ON royal_canin.log_dq_issue (sku_id);
COMMENT ON TABLE royal_canin.log_dq_issue IS 'temuan data quality untuk data steward';
COMMENT ON COLUMN royal_canin.log_dq_issue.logged_at IS 'timestamptz: instan waktu absolut; tampil dalam Asia/Jakarta (WIB) pada session TimeZone default';

-- DM_TRAFFIC: view atas T_TRAFFIC
CREATE OR REPLACE VIEW royal_canin.dm_traffic AS
SELECT t.period_start, t.period_end, t.channel_id, c.channel_code, t.visitor
FROM royal_canin.t_traffic t
JOIN royal_canin.m_channel c ON c.channel_id = t.channel_id;
COMMENT ON VIEW royal_canin.dm_traffic IS 'VIEW atas T_TRAFFIC';

COMMENT ON COLUMN royal_canin.t_order.order_date IS 'GENERATED: tanggal WIB dari order_created_at (AT TIME ZONE ''Asia/Jakarta'')';
COMMENT ON COLUMN royal_canin.m_channel.order_ts_format IS 'format to_timestamp jam order di file mentah (jam dinding WIB); dipakai: royal_canin.to_jakarta_ts(kolom_waktu, order_ts_format)';
COMMENT ON COLUMN royal_canin.m_sku.master_sku IS 'kode seller SKU terkini (golden record, hasil survivorship R4)';
COMMENT ON COLUMN royal_canin.m_sku.sku_master_code IS 'id bisnis SKU master, mis. SKU-00001';
COMMENT ON COLUMN royal_canin.m_sku.bundle_flag IS 'true bila SKU didefinisikan sebagai bundle di file Detail SKU Bundle';
COMMENT ON COLUMN royal_canin.m_sku_alias.sku_code IS 'seller SKU yang sudah distandardisasi (R1), mis. TKP_25220040 -> 25220040';
COMMENT ON COLUMN royal_canin.m_platform_sku.merchant_sku IS 'SKU ID platform; Shopee: SHP_ + md5(nama produk|variasi)[:12]';
COMMENT ON COLUMN royal_canin.m_sku_bundle.component_sku_id IS 'komponen yang belum pernah terjual ditambahkan ke m_sku (dq_flag from_bundle_master), sehingga selalu terisi';
COMMENT ON COLUMN royal_canin.m_sku_bundle.component_price IS 'harga satuan komponen dari file bundling price; 0 untuk hadiah gratis (kode 37/B... atau nama berawalan "B - ")';
COMMENT ON COLUMN royal_canin.m_sku_bundle.price_ratio IS 'porsi harga komponen dalam bundle = harga x qty / total (harga x qty); jumlah per bundle = 1; pembagi alokasi GMV item bundle. Bila ada harga kosong atau semua harga 0: rasio qty dan dq_flag equal_split';
COMMENT ON COLUMN royal_canin.m_sku_bundle.dq_flag IS 'daftar dipisah koma: free_gift, flattened, equal_split, price_gap, qty_missing, dup_component, nested_bundle';
COMMENT ON COLUMN royal_canin.t_order.gmv_2 IS 'GMV level order: nilai order diambil sekali per order bila m_channel.gmv2_dedup_by_order (Shopee, TikTok, Tokopedia), selain itu dijumlah per baris item (Lazada, Blibli)';
COMMENT ON COLUMN royal_canin.t_order_detail.gmv_1 IS 'GMV level item = harga awal x qty sebelum diskon; item bundle dibagi ke komponen dengan m_sku_bundle.price_ratio';
COMMENT ON COLUMN royal_canin.t_order_detail.line_key IS 'id baris marketplace, atau <SKU platform>:<urutan>; komponen bundle diberi akhiran #<component_seq>';
COMMENT ON COLUMN royal_canin.t_order_detail.sku_id IS 'SKU hasil: untuk item bundle = SKU komponen (platform_sku_id tetap listing yang dijual)';
COMMENT ON COLUMN royal_canin.t_order_detail.is_bundle IS 'true bila baris berasal dari penguraian SKU bundle';
COMMENT ON COLUMN royal_canin.t_order_detail.quantity IS 'qty order x qty komponen untuk item bundle';
COMMENT ON COLUMN royal_canin.t_order_detail.sku_id IS 'NULL bila seller SKU belum terpetakan ke M_SKU (lihat LOG_DQ_ISSUE)';
COMMENT ON COLUMN royal_canin.dm_sales_daily.warehouse_name IS 'bagian PK: ETL mengisi ''UNKNOWN'' bila kosong';
COMMENT ON COLUMN royal_canin.dm_sales_sku_daily.unit_sold_component IS 'unit setelah bundle di-explode via M_SKU_BUNDLE';

-- seed channel (gmv2_dedup_by_order: true = nilai order muncul berulang di tiap baris item, diambil sekali per order)
-- order_ts_format = format jam order di file mentah (contoh nilai di komentar)
INSERT INTO royal_canin.m_channel (channel_code, channel_name, sku_source_column, order_ts_format, gmv2_dedup_by_order) VALUES
    ('SHOPEE',    'Shopee',      'Nomor Referensi SKU', 'YYYY-MM-DD HH24:MI',      true),   -- 2026-01-01 00:00
    ('TOKOPEDIA', 'Tokopedia',   'Seller SKU',          'DD/MM/YYYY HH24:MI:SS',   true),   -- 31/01/2026 23:40:26
    ('TIKTOK',    'TikTok Shop', 'Seller SKU',          'DD/MM/YYYY HH24:MI:SS',   true),   -- 31/01/2026 23:43:59
    ('LAZADA',    'Lazada',      'sellerSku',           'DD Mon YYYY HH24:MI',     false),  -- 30 Sep 2026 22:34
    ('BLIBLI',    'Blibli',      'SKU seller',          'DD/MM/YYYY HH24:MI',      false)   -- 01/01/2026 13:56
ON CONFLICT (channel_code) DO UPDATE SET order_ts_format = EXCLUDED.order_ts_format,
                                         gmv2_dedup_by_order = EXCLUDED.gmv2_dedup_by_order;

COMMIT;
